; arith.asm -- chapter 2: eight sums, and a 16-bit number in memory
; generated by gen02.py
        INCLUDE "msx.inc"
        OUTPUT "arith.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
result  EQU VARS + 4              ; the result and the flags of the last sum
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 2
        ld c, 0
        ld hl, h_sum
        call puts
        ld c, 8
        ld hl, h_bits
        call puts
        ld c, 17
        ld hl, h_hex
        call puts
        ld c, 21
        ld hl, h_dec
        call puts
        ld c, 25
        ld hl, h_sgn
        call puts
        ld c, 30
        ld hl, h_C
        call puts
        ld c, 31
        ld hl, h_V
        call puts
; 3+5
        ld a, 3
        ld e, 5
        add a, e
        push af
        pop hl                  ; H: the result, L: the flags
        ld (result), hl
        ld b, 4
        ld c, 0
        ld hl, t0
        call puts
        ld c, 8
        ld a, (result + 1)
        call fatbits
        ld c, 17
        ld a, (result + 1)
        call puthex
        ld c, 21
        ld a, (result + 1)
        call putdec
        ld c, 25
        ld a, (result + 1)
        call putsgn
        call flags
; 200+100
        ld a, 200
        ld e, 100
        add a, e
        push af
        pop hl                  ; H: the result, L: the flags
        ld (result), hl
        ld b, 6
        ld c, 0
        ld hl, t1
        call puts
        ld c, 8
        ld a, (result + 1)
        call fatbits
        ld c, 17
        ld a, (result + 1)
        call puthex
        ld c, 21
        ld a, (result + 1)
        call putdec
        ld c, 25
        ld a, (result + 1)
        call putsgn
        call flags
; 255+1
        ld a, 255
        ld e, 1
        add a, e
        push af
        pop hl                  ; H: the result, L: the flags
        ld (result), hl
        ld b, 8
        ld c, 0
        ld hl, t2
        call puts
        ld c, 8
        ld a, (result + 1)
        call fatbits
        ld c, 17
        ld a, (result + 1)
        call puthex
        ld c, 21
        ld a, (result + 1)
        call putdec
        ld c, 25
        ld a, (result + 1)
        call putsgn
        call flags
; 127+1
        ld a, 127
        ld e, 1
        add a, e
        push af
        pop hl                  ; H: the result, L: the flags
        ld (result), hl
        ld b, 10
        ld c, 0
        ld hl, t3
        call puts
        ld c, 8
        ld a, (result + 1)
        call fatbits
        ld c, 17
        ld a, (result + 1)
        call puthex
        ld c, 21
        ld a, (result + 1)
        call putdec
        ld c, 25
        ld a, (result + 1)
        call putsgn
        call flags
; 128+128
        ld a, 128
        ld e, 128
        add a, e
        push af
        pop hl                  ; H: the result, L: the flags
        ld (result), hl
        ld b, 12
        ld c, 0
        ld hl, t4
        call puts
        ld c, 8
        ld a, (result + 1)
        call fatbits
        ld c, 17
        ld a, (result + 1)
        call puthex
        ld c, 21
        ld a, (result + 1)
        call putdec
        ld c, 25
        ld a, (result + 1)
        call putsgn
        call flags
; 100-30
        ld a, 100
        ld e, 30
        sub e
        push af
        pop hl                  ; H: the result, L: the flags
        ld (result), hl
        ld b, 14
        ld c, 0
        ld hl, t5
        call puts
        ld c, 8
        ld a, (result + 1)
        call fatbits
        ld c, 17
        ld a, (result + 1)
        call puthex
        ld c, 21
        ld a, (result + 1)
        call putdec
        ld c, 25
        ld a, (result + 1)
        call putsgn
        call flags
; 5-7
        ld a, 5
        ld e, 7
        sub e
        push af
        pop hl                  ; H: the result, L: the flags
        ld (result), hl
        ld b, 16
        ld c, 0
        ld hl, t6
        call puts
        ld c, 8
        ld a, (result + 1)
        call fatbits
        ld c, 17
        ld a, (result + 1)
        call puthex
        ld c, 21
        ld a, (result + 1)
        call putdec
        ld c, 25
        ld a, (result + 1)
        call putsgn
        call flags
; 0-1
        ld a, 0
        ld e, 1
        sub e
        push af
        pop hl                  ; H: the result, L: the flags
        ld (result), hl
        ld b, 18
        ld c, 0
        ld hl, t7
        call puts
        ld c, 8
        ld a, (result + 1)
        call fatbits
        ld c, 17
        ld a, (result + 1)
        call puthex
        ld c, 21
        ld a, (result + 1)
        call putdec
        ld c, 25
        ld a, (result + 1)
        call putsgn
        call flags
; a 16-bit number stored in memory, and its two bytes read back
        ld hl, $1234
        ld ($C000), hl
        ld b, 21
        ld c, 0
        ld hl, t_hl
        call puts
        ld a, $12
        call puthex
        ld a, $34
        call puthex
        ld hl, t_lo
        call puts
        ld a, ($C000)
        call puthex
        ld hl, t_hi
        call puts
        ld a, ($C001)
        call puthex
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; flags: the carry flag (bit 0 of F) and the overflow flag (bit 2), as the
;        letters C and V, or a dash
flags:  ld c, 30
        ld a, (result)
        and %00000001
        ld a, '-'
        jr z, .noc
        ld a, 'C'
.noc:   call putc
        ld c, 31
        ld a, (result)
        and %00000100
        ld a, '-'
        jr z, .nov
        ld a, 'V'
.nov:   jp putc

t0:     db "3+5", 0
t1:     db "200+100", 0
t2:     db "255+1", 0
t3:     db "127+1", 0
t4:     db "128+128", 0
t5:     db "100-30", 0
t6:     db "5-7", 0
t7:     db "0-1", 0
h_sum:   db "sum", 0
h_bits:  db "bits", 0
h_hex:   db "hex", 0
h_dec:   db "dec", 0
h_sgn:   db "sgn", 0
h_C:     db "C", 0
h_V:     db "V", 0
t_hl:   db "HL=$", 0
t_lo:   db "  $C000:", 0
t_hi:   db "  $C001:", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret

; putdec: A = a byte taken as unsigned (0-255): three characters, right-aligned
; putsgn: A = a byte taken as signed (-128 to 127): four characters
;         C moves on by 3 or 4. Uses A, DE, HL.
putdec: push bc
        ld d, ' '
        call digits
        pop bc
        ld hl, numbuf + 1
        ld e, 3
        jr pnout
putsgn: push bc
        ld d, ' '
        bit 7, a                ; the top bit is the sign
        jr z, .pos
        neg                     ; two's complement: the size of the number
        ld d, '-'
.pos:   call digits
        pop bc
        ld hl, numbuf
        ld e, 4
pnout:  ld a, (hl)
        call putc
        inc c
        inc hl
        dec e
        jr nz, pnout
        ret

; digits: A (0-255) into numbuf in decimal, right-aligned, D just left of
;         the first digit. Uses A, C, HL.
digits: ld hl, numbuf
        ld (hl), ' '
        inc hl
        ld (hl), ' '
        inc hl
        ld (hl), ' '
        inc hl
        ld (hl), ' '            ; HL: the last character
.next:  ld c, 0                 ; C: A divided by 10
.ten:   cp 10
        jr c, .rest
        sub 10
        inc c
        jr .ten
.rest:  add a, '0'
        ld (hl), a              ; the remainder is this digit
        dec hl
        ld a, c
        or a
        jr nz, .next            ; and the quotient is what is left
        ld (hl), d              ; the sign, or a space
        ret
numbuf  EQU VARS                ; 4 bytes of RAM

; fatbits: A = a byte, drawn as 8 boxes, bit 7 first: a filled box for 1,
;          an empty one for 0. B = row, C = column; C moves on by 8.
;          Uses A. Keeps HL.
fatbits:
        push hl
        ld l, a
        ld h, 8
.bit:   ld a, 1                 ; an empty box ...
        rl l                    ; the next bit, into the carry
        jr nc, .put
        ld a, 2                 ; ... or a filled one
.put:   call putc
        inc c
        dec h
        jr nz, .bit
        pop hl
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
